{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.STORE_RETURN_INVENTORY_LOG AS WITH latest AS ( SELECT * FROM S3_INVENTORY_LOG WHERE UPPER(TRIM(OPERATION_TYPE::VARCHAR)) = \'STORE_OUTWARD\' QUALIFY ROW_NUMBER() OVER ( PARTITION BY ID ORDER BY TRY_TO_TIMESTAMP_TZ( _AB_SOURCE_FILE_LAST_MODIFIED::VARCHAR ) DESC NULLS LAST, TRY_TO_TIMESTAMP_TZ( _AIRBYTE_EMITTED_AT::VARCHAR ) DESC NULLS LAST, TRY_TO_TIMESTAMP_TZ( _AIRBYTE_NORMALIZED_AT::VARCHAR ) DESC NULLS LAST, _AIRBYTE_AB_ID DESC ) = 1 ), parsed AS ( SELECT *, TRY_PARSE_JSON(DISPATCH_META::VARCHAR) AS meta FROM latest ) SELECT ID::VARCHAR AS line_id, UPPER(NULLIF(TRIM(REFERENCE_ID::VARCHAR), \'\')) AS reference_id, UPPER(NULLIF(TRIM(ORDER_ID::VARCHAR), \'\')) AS order_id, NULLIF(TRIM(BRANCH_CODE_FROM::VARCHAR), \'\') AS branch_code_from, NULLIF(TRIM(BRANCH_CODE_TO::VARCHAR), \'\') AS branch_code_to, UPPER(NULLIF(TRIM(MOVEMENT_TYPE::VARCHAR), \'\')) AS movement_type, UPPER(NULLIF(TRIM(SKU::VARCHAR), \'\')) AS sku, NULLIF(TRIM(BOX_NAME::VARCHAR), \'\') AS box_name, LOWER(NULLIF(TRIM(STATUS::VARCHAR), \'\')) AS line_status, TRY_TO_NUMBER(REQUESTED_QUANTITY::VARCHAR) AS requested_qty_log, TRY_TO_NUMBER(PICKED_QUANTITY::VARCHAR) AS picked_qty_log, TRY_TO_NUMBER(PACKED_QUANTITY::VARCHAR) AS packed_qty_log, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(CREATED_AT::VARCHAR) ) AS created_at_ist, UPPER(NULLIF(TRIM(LOGIC_REFERENCE::VARCHAR), \'\')) AS logic_reference, UPPER(NULLIF(TRIM(meta:awb_number::VARCHAR), \'\')) AS oms_awb, NULLIF(TRIM(meta:eshipz_order_id::VARCHAR), \'\') AS eshipz_order_id, LOWER(NULLIF(TRIM(meta:transporter_slug::VARCHAR), \'\')) AS transporter_slug, meta:transporter_name::VARCHAR AS transporter_name, TRY_TO_BOOLEAN(meta:is_qcom::VARCHAR) AS is_qcom, LOWER(meta:eshipz_sync_status::VARCHAR) AS eshipz_sync_status, meta:eshipz_failure_message::VARCHAR AS eshipz_failure_message, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(meta:packed_at::VARCHAR) ) AS packed_at_ist, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(meta:logic_pushed_at::VARCHAR) ) AS logic_pushed_at_ist, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(meta:eshipz_pushed_at::VARCHAR) ) AS eshipz_pushed_at_ist, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(meta:dispatched_at::VARCHAR) ) AS oms_dispatched_at_ist, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(meta:complete_dispatch_at::VARCHAR) ) AS complete_dispatch_at_ist, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(meta:eshipz_failed_at::VARCHAR) ) AS eshipz_failed_at_ist, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(meta:transporter_selected_at::VARCHAR) ) AS transporter_selected_at_ist, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(meta:cancelled_at::VARCHAR) ) AS cancelled_at_ist, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP_NTZ(meta:inventory_unavailable_at::VARCHAR) ) AS inventory_unavailable_at_ist, ( NULLIF(TRIM(DISPATCH_META::VARCHAR), \'\') IS NOT NULL AND NOT COALESCE(IS_OBJECT(meta), FALSE) ) AS dispatch_meta_invalid FROM parsed; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.STORE_RETURN_OPERATIONS AS WITH warehouse_map AS ( SELECT column1::VARCHAR AS warehouse_code, column2::VARCHAR AS warehouse_name, column3::VARCHAR AS warehouse_region FROM VALUES (\'995\', \'SAPL-WH1\', \'SOUTH\'), (\'999\', \'SAPL-WH2\', \'SOUTH\'), (\'998\', \'SAPL-NORTH-TAURU\', \'NORTH\') ), store_master AS ( SELECT TRIM(BRANCH_CODE::VARCHAR) AS store_code, NULLIF(TRIM(STORE_NAME_FORMAT::VARCHAR), \'\') AS store_name, NULLIF(TRIM(STATE::VARCHAR), \'\') AS store_state, NULLIF(TRIM(CHANNEL::VARCHAR), \'\') AS store_channel FROM SNITCH_DB.MAPLEMONK.GS_STORE_DETAILS WHERE NULLIF(TRIM(BRANCH_CODE::VARCHAR), \'\') IS NOT NULL AND TRIM(BRANCH_CODE::VARCHAR) <> \'0\' AND NULLIF(TRIM(STORE_NAME_FORMAT::VARCHAR), \'\') IS NOT NULL QUALIFY ROW_NUMBER() OVER ( PARTITION BY TRIM(BRANCH_CODE::VARCHAR) ORDER BY IFF(UPPER(STORE_NAME_FORMAT::VARCHAR) LIKE \'% - QC %\', 1, 0), TRY_TO_TIMESTAMP_TZ(_AIRBYTE_EMITTED_AT::VARCHAR) DESC NULLS LAST, TRY_TO_TIMESTAMP_TZ(_AIRBYTE_NORMALIZED_AT::VARCHAR) DESC NULLS LAST, STORE_NAME_FORMAT::VARCHAR, STATE::VARCHAR, CHANNEL::VARCHAR ) = 1 ), order_context AS ( SELECT branch_code_from, reference_id, order_id, MIN(created_at_ist) AS order_timestamp, COUNT(DISTINCT oms_awb) AS known_awb_count, IFF(COUNT(DISTINCT oms_awb) = 1, MAX(oms_awb), NULL) AS single_awb, IFF(COUNT(DISTINCT logic_reference) = 1, MAX(logic_reference), NULL) AS single_logic_reference FROM SNITCH_DB.MAPLEMONK.STORE_RETURN_INVENTORY_LOG GROUP BY branch_code_from, reference_id, order_id ), lines AS ( SELECT l.*, c.order_timestamp, c.known_awb_count, COALESCE(l.oms_awb, c.single_awb) AS effective_awb, COALESCE(l.logic_reference, c.single_logic_reference) AS effective_logic_reference FROM SNITCH_DB.MAPLEMONK.STORE_RETURN_INVENTORY_LOG l JOIN order_context c ON l.branch_code_from = c.branch_code_from AND l.reference_id = c.reference_id AND l.order_id = c.order_id ), oms AS ( SELECT CONCAT_WS(\'|\', branch_code_from, reference_id, order_id, COALESCE(branch_code_to, \'\'), COALESCE(effective_awb, \'\'), COALESCE(effective_logic_reference, \'\')) AS row_key, CONCAT_WS(\'|\', branch_code_from, reference_id, order_id) AS request_key, reference_id, order_id AS order_name, branch_code_from AS store_code, branch_code_to AS warehouse_code, effective_awb AS oms_awb, effective_logic_reference AS shipment_bill, MIN(order_timestamp) AS order_timestamp, MAX(known_awb_count) AS known_awb_count, IFF(COUNT(DISTINCT transporter_slug) = 1, MAX(transporter_slug), NULL) AS oms_courier, IFF(COUNT(DISTINCT transporter_name) = 1, MAX(transporter_name), NULL) AS transporter_name, IFF(COUNT(DISTINCT movement_type) = 1, MAX(movement_type), NULL) AS movement_type, MAX(IFF(is_qcom, 1, 0)) = 1 AS is_qcom, COUNT(*) AS inventory_line_count, COUNT(DISTINCT sku) AS sku_count, COUNT(DISTINCT box_name) AS box_count, SUM(requested_qty_log) AS requested_quantity, SUM(picked_qty_log) AS picked_quantity, SUM(packed_qty_log) AS packed_quantity, SUM(IFF(line_status = \'cancelled\', requested_qty_log, 0)) AS cancelled_quantity, COALESCE(COUNT_IF(line_status = \'cancelled\'), 0) AS cancelled_line_count, COALESCE(COUNT_IF(line_status IN (\'inventory_unavailable\', \'not_found\')), 0) AS unavailable_line_count, COALESCE(COUNT_IF(line_status IS NULL OR line_status NOT IN (\'dispatched\', \'complete_dispatch\', \'cancelled\')), 0) AS open_store_line_count, COALESCE(COUNT_IF(eshipz_sync_status = \'failed\'), 0) AS booking_failed_line_count, LISTAGG(DISTINCT eshipz_failure_message, \'; \') WITHIN GROUP (ORDER BY eshipz_failure_message) AS booking_failure_message, COALESCE(COUNT_IF(dispatch_meta_invalid), 0) AS invalid_meta_line_count, COALESCE(COUNT_IF(requested_qty_log IS NULL OR picked_qty_log IS NULL OR packed_qty_log IS NULL), 0) AS invalid_quantity_line_count, MIN(packed_at_ist) AS first_packed_timestamp, MAX(packed_at_ist) AS packed_timestamp, MIN(logic_pushed_at_ist) AS logic_pushed_timestamp, MIN(eshipz_pushed_at_ist) AS eshipz_pushed_timestamp, MIN(oms_dispatched_at_ist) AS first_store_dispatch_timestamp, IFF(COUNT_IF(COALESCE(line_status, \'\') <> \'cancelled\') > 0 AND COALESCE(COUNT_IF(COALESCE(line_status, \'\') <> \'cancelled\' AND oms_dispatched_at_ist IS NULL), 0) = 0, MAX(IFF(COALESCE(line_status, \'\') <> \'cancelled\', oms_dispatched_at_ist, NULL)), NULL) AS store_completed_timestamp, MAX(complete_dispatch_at_ist) AS complete_dispatch_timestamp FROM lines GROUP BY branch_code_from, reference_id, order_id, branch_code_to, effective_awb, effective_logic_reference ), shipment_projection AS ( SELECT DISTINCT UPPER(NULLIF(TRIM(TRACKING_NUMBER::VARCHAR), \'\')) AS tracking_number, UPPER(NULLIF(TRIM(COURIER_PARTNER::VARCHAR), \'\')) AS courier_partner, UPPER(NULLIF(TRIM(UNIQUE_ORDER_ID::VARCHAR), \'\')) AS invoice_reference, NULLIF(TRIM(FROM_PARTY::VARCHAR), \'\') AS store_name, NULLIF(TRIM(TO_PARTY::VARCHAR), \'\') AS destination_name, NULLIF(TRIM(RECEIVER_COMPANY_NAME::VARCHAR), \'\') AS receiver_name, UPPER(STATUS::VARCHAR) AS status, UPPER(FINAL_STATUS::VARCHAR) AS final_status, ESHIP_STATUS, LOGISTICS_CREATED_TIMESTAMP, LAST_UPDATED_TIMESTAMP, LOGISTICS_DELIVERY_TIMESTAMP, LOGISTICS_EXPECTED_DELIVERY_DATE, TRACKING_PICK_DATE, FIRST_OFD_DATE, LATEST_OFD_DATE, DELIVERY_ATTEMPTS, PICKUP_ATTEMPTS, TRACKING_LINK, POD_LINK, TRACKING_STATUS, TRACKING_SUB_STATUS, TRACKING_LATEST_LOCATION, TRACKING_LATEST_MESSAGE, LAST_CHECKPOINT_CITY, LAST_CHECKPOINT_STATE, RECEIVER_CITY, RECEIVER_STATE, ZONE, PICKUP_TAT, DELIVERY_TAT, PICKUP_SLA, DELIVERY_SLA, LOGISTICS_DELIVERY_SLA FROM SNITCH_DB.MAPLEMONK.FINAL_ESHIP_TRACKING WHERE IS_REVERSE = TRUE AND NULLIF(TRIM(TRACKING_NUMBER::VARCHAR), \'\') IS NOT NULL ), shipment_keys AS ( SELECT DISTINCT courier_partner, tracking_number, invoice_reference FROM shipment_projection ), shipments AS ( SELECT p.*, HASH(p.*) AS row_tiebreaker FROM shipment_projection p QUALIFY ROW_NUMBER() OVER ( PARTITION BY courier_partner, tracking_number ORDER BY LAST_UPDATED_TIMESTAMP DESC NULLS LAST, LOGISTICS_CREATED_TIMESTAMP DESC NULLS LAST, row_tiebreaker DESC ) = 1 ), candidates AS ( SELECT DISTINCT o.row_key, k.courier_partner, k.tracking_number, IFF(o.oms_awb IS NOT NULL, \'AWB\', \'INVOICE\') AS match_method FROM oms o JOIN shipment_keys k ON (o.oms_awb IS NOT NULL AND o.oms_awb = k.tracking_number) OR (o.oms_awb IS NULL AND o.known_awb_count = 0 AND o.shipment_bill IS NOT NULL AND o.shipment_bill = k.invoice_reference) ), match_counts AS ( SELECT row_key, COUNT(*) AS candidate_count FROM candidates GROUP BY row_key ), unique_matches AS ( SELECT c.* FROM candidates c JOIN match_counts n ON c.row_key = n.row_key AND n.candidate_count = 1 ), flat AS ( SELECT o.*, COALESCE(s.tracking_number, o.oms_awb) AS tracking_number, COALESCE(s.courier_partner, UPPER(o.oms_courier)) AS courier_partner, COALESCE(sm.store_name, s.store_name, \'STORE CODE \' || o.store_code) AS store, sm.store_state, sm.store_channel, CASE WHEN sm.store_name IS NOT NULL THEN \'GS_STORE_DETAILS\' WHEN s.store_name IS NOT NULL THEN \'ESHIPZ\' ELSE \'BRANCH_CODE_ONLY\' END AS store_name_source, COALESCE(w.warehouse_name, s.destination_name, s.receiver_name, \'DESTINATION CODE \' || o.warehouse_code) AS warehouse_name, w.warehouse_region, COALESCE(o.shipment_bill, s.invoice_reference) AS invoice_number, COALESCE(n.candidate_count, 0) AS tracking_candidate_count, CASE WHEN n.candidate_count > 1 THEN \'AMBIGUOUS_TRACKING_MATCH\' WHEN m.row_key IS NOT NULL THEN \'MATCHED_\' || m.match_method WHEN o.oms_awb IS NOT NULL THEN \'AWB_NOT_IN_TRACKING\' ELSE \'NOT_LINKED_TO_TRACKING\' END AS tracking_match_status, s.status, s.final_status, s.eship_status, REGEXP_REPLACE(COALESCE(s.final_status, s.status, \'\'), \'[^A-Z0-9]\', \'\') AS status_key, s.logistics_created_timestamp, COALESCE(s.logistics_created_timestamp, o.first_store_dispatch_timestamp) AS pickup_request_timestamp, s.last_updated_timestamp, s.logistics_delivery_timestamp, s.logistics_expected_delivery_date, s.tracking_pick_date, s.first_ofd_date, s.latest_ofd_date, s.delivery_attempts, s.pickup_attempts, s.tracking_link, s.pod_link, s.tracking_status, s.tracking_sub_status, s.tracking_latest_location, s.tracking_latest_message, s.last_checkpoint_city, s.last_checkpoint_state, s.receiver_city, s.receiver_state, s.zone, s.pickup_tat, s.delivery_tat, s.pickup_sla, s.delivery_sla, s.logistics_delivery_sla FROM oms o LEFT JOIN unique_matches m ON o.row_key = m.row_key LEFT JOIN match_counts n ON o.row_key = n.row_key LEFT JOIN shipments s ON m.tracking_number = s.tracking_number AND EQUAL_NULL(m.courier_partner, s.courier_partner) LEFT JOIN warehouse_map w ON o.warehouse_code = w.warehouse_code LEFT JOIN store_master sm ON o.store_code = sm.store_code ) SELECT order_name, order_timestamp, order_timestamp::DATE AS order_date, store_code, store, store_state, store_channel, warehouse_code, warehouse_name, warehouse_region, movement_type, is_qcom, transporter_name, tracking_number, courier_partner, invoice_number, shipment_bill, requested_quantity, picked_quantity, packed_quantity, cancelled_quantity, box_count, sku_count, packed_timestamp, logic_pushed_timestamp, eshipz_pushed_timestamp, first_store_dispatch_timestamp, store_completed_timestamp, complete_dispatch_timestamp, pickup_request_timestamp, logistics_created_timestamp, tracking_pick_date, logistics_delivery_timestamp, logistics_expected_delivery_date, first_ofd_date, latest_ofd_date, status, final_status, eship_status, CASE WHEN status_key IN (\'CANCELLED\', \'CANCELED\', \'DELETED\') THEN \'CANCELLED\' WHEN status_key IN (\'RETURN\', \'RETURNED\', \'RETURNTOORIGIN\', \'RTO\', \'RTOINITIATED\', \'RTODELIVERED\', \'RETURNDELIVERED\') THEN \'RETURN_TO_ORIGIN\' WHEN status_key = \'DELIVERED\' THEN \'DELIVERED\' WHEN status_key IN (\'OUTFORDELIVERY\', \'OFD\') THEN \'OUT_FOR_DELIVERY\' WHEN status_key IN (\'EXCEPTION\', \'UNDELIVERED\', \'FAILEDATTEMPT\', \'DAMAGED\') OR status_key LIKE \'LOST%\' THEN \'EXCEPTION\' WHEN status_key IN (\'INTRANSIT\', \'PICKEDUP\', \'DISPATCHED\') OR tracking_pick_date IS NOT NULL THEN \'IN_TRANSIT\' WHEN cancelled_line_count = inventory_line_count THEN \'CANCELLED\' WHEN tracking_candidate_count > 1 OR (tracking_match_status NOT LIKE \'MATCHED_%\' AND (tracking_number IS NOT NULL OR pickup_request_timestamp IS NOT NULL)) THEN \'TRACKING_PENDING\' WHEN status_key NOT IN (\'\', \'INFORECEIVED\', \'MANIFESTED\', \'PENDING\', \'REGISTERED\', \'BOOKED\', \'AWAITINGPICKUP\', \'PICKUPREGISTERED\') THEN \'TRACKING_STATUS_REVIEW\' WHEN pickup_request_timestamp IS NOT NULL OR tracking_number IS NOT NULL THEN \'READY_FOR_PICKUP\' WHEN booking_failed_line_count > 0 THEN \'BOOKING_FAILED\' WHEN cancelled_line_count + unavailable_line_count = inventory_line_count THEN \'STOCK_UNAVAILABLE\' WHEN logic_pushed_timestamp IS NOT NULL OR packed_timestamp IS NOT NULL THEN \'AWAITING_BOOKING\' ELSE \'STORE_PROCESSING\' END AS overall_status, CASE WHEN cancelled_line_count = inventory_line_count THEN \'CANCELLED\' WHEN store_completed_timestamp IS NOT NULL THEN \'COMPLETED\' WHEN first_store_dispatch_timestamp IS NOT NULL THEN \'PARTIAL_DISPATCH\' WHEN packed_timestamp IS NOT NULL THEN \'PACKING_OR_BOOKING\' ELSE \'PROCESSING\' END AS store_processing_status, tracking_match_status, open_store_line_count, unavailable_line_count, cancelled_line_count, booking_failed_line_count, NULLIF(booking_failure_message, \'\') AS booking_failure_message, delivery_attempts, pickup_attempts, tracking_link, pod_link, tracking_status, tracking_sub_status, tracking_latest_location, tracking_latest_message, last_checkpoint_city, last_checkpoint_state, receiver_city, receiver_state, zone, pickup_tat, delivery_tat, pickup_sla, delivery_sla, logistics_delivery_sla, DATEDIFF(\'second\', order_timestamp, store_completed_timestamp) / 60.0 AS store_processing_minutes, last_updated_timestamp, GREATEST_IGNORE_NULLS(order_timestamp, packed_timestamp, first_store_dispatch_timestamp, last_updated_timestamp, tracking_pick_date, logistics_delivery_timestamp) AS spine_last_event_ts, store_name_source, invalid_meta_line_count, invalid_quantity_line_count, tracking_candidate_count, inventory_line_count, reference_id, request_key, row_key, IFF(tracking_number IS NOT NULL, CONCAT_WS(\'|\', COALESCE(courier_partner, \'\'), tracking_number), NULL) AS shipment_key, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::TIMESTAMP_NTZ AS snapshot_refreshed_at_ist FROM flat;",
                    "transaction": true
                }
            ) }}
